package com.yihe.framework.ehr;
import com.fasterxml.jackson.databind.ObjectMapper;import org.springframework.beans.factory.annotation.Value;import org.springframework.web.bind.annotation.*;import javax.servlet.http.*;import java.nio.file.*;import java.util.*;import java.util.regex.*;import java.io.*;import static com.yihe.framework.ehr.EhrAccess.*;import static com.yihe.framework.ehr.EhrController.ok;
@RestController @RequestMapping("/ehr/api/assessment-rules")
public class AssessmentRuleApi {
 private final EhrAccess access;private final EhrRepository db;private final ObjectMapper json=new ObjectMapper();@Value("${ehr.storage-root:${EHR_STORAGE_ROOT:D:/update}}") private String storage;
 public AssessmentRuleApi(EhrAccess access,EhrRepository db){this.access=access;this.db=db;}@ModelAttribute public void headers(HttpServletResponse r){r.setHeader("Cache-Control","private, no-store");}
 private String s(Object v){return v==null?"":String.valueOf(v);}private void check(boolean b,String m){if(!b)throw new EhrException(422,m);}private Path file(EhrActor a){return Paths.get(storage,".assessment-rules",Base64.getUrlEncoder().withoutPadding().encodeToString(digest(bytes(a.scope+":"+a.mode)))+".json");}
 @SuppressWarnings("unchecked") private List<Map<String,Object>> rows(Object v,int max){check(v instanceof List&&((List<?>)v).size()<=max,"配置列表无效或超过限制");List<Map<String,Object>> out=new ArrayList<>();for(Object r:(List<?>)v){check(r instanceof Map,"配置行格式无效");out.add((Map<String,Object>)r);}return out;}
 private Map<String,Object> initial(){List<Object> groups=new ArrayList<>(),rules=new ArrayList<>();for(Map<String,Object> g:db.all("SELECT typeid id,typename name FROM yh_data_detection_type ORDER BY COALESCE(point,9999),typeid"))groups.add(map("id","legacy-group-"+g.get("id"),"name",g.get("name"),"kind","indicator"));for(String kind:Arrays.asList("risk","composite","segments"))groups.add(map("id",kind,"name",kind.equals("risk")?"风险判定规则":kind.equals("composite")?"综合评估规则":"分层分群规则","kind",kind));Map<String,Map<String,Object>> grouped=new LinkedHashMap<>();for(Map<String,Object> r:db.all("SELECT p.projectid,p.projectname name,p.tid,p.state projectState,r.referenceid,r.unit,r.reference_range referenceRange,r.state referenceState,s.standardid,s.standard,s.anomaly_level,s.state,s.evaluate,s.applicable_gender gender,s.applicable_min_age minAge,s.applicable_max_age maxAge FROM yh_data_detection_project_standard s JOIN yh_data_detection_reference r ON r.referenceid=s.rid JOIN yh_data_detection_project p ON p.projectid=r.pid WHERE s.standard IS NOT NULL AND TRIM(s.standard)<>'' ORDER BY p.projectid,r.referenceid,s.anomaly_level DESC,s.standardid")){String id="source-"+r.get("projectid")+"-"+r.get("referenceid"),metric="LEGACY-"+r.get("projectid")+"-"+r.get("referenceid");Map<String,Object> rule=grouped.get(id);if(rule==null){rule=map("id",id,"name",s(r.get("name"))+"评估","kind","indicator","groupId","legacy-group-"+r.get("tid"),"metrics",Arrays.asList(metric),"method","threshold","enabled","0".equals(s(r.get("projectState")))&&"0".equals(s(r.get("referenceState"))),"description","来自现有检测项目评价标准","reference","","referenceUrl","","unit",s(r.get("unit")),"conditions",new ArrayList<>(),"revision",1);grouped.put(id,rule);} @SuppressWarnings("unchecked") List<Object> conditions=(List<Object>)rule.get("conditions");conditions.add(map("id","standard-"+r.get("standardid"),"level","0".equals(s(r.get("state")))?"normal":"abnormal","label",s(r.get("evaluate")).isEmpty()?"原等级 "+r.get("anomaly_level"):r.get("evaluate"),"raw",s(r.get("standard")),"logic","all","clauses",new ArrayList<>(),"gender",r.get("gender"),"minAge",r.get("minAge"),"maxAge",r.get("maxAge")));}rules.addAll(grouped.values());return map("version",0,"groups",groups,"rules",rules,"history",new ArrayList<>());}
 @SuppressWarnings("unchecked") private Map<String,Object> read(EhrActor a)throws IOException{Path p=file(a);if(!Files.exists(p))return initial();check(Files.size(p)<12582912,"规则文件过大");return json.readValue(Files.readAllBytes(p),Map.class);}
 private void write(EhrActor a,Map<String,Object> data)throws IOException{byte[] content=json.writeValueAsBytes(data);check(content.length<=12582912,"规则配置超过12MB");Path p=file(a);Files.createDirectories(p.getParent());Path tmp=Files.createTempFile(p.getParent(),"rules-",".tmp");try{Files.write(tmp,content);try{Files.move(tmp,p,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}catch(AtomicMoveNotSupportedException ex){Files.move(tmp,p,StandardCopyOption.REPLACE_EXISTING);}}finally{Files.deleteIfExists(tmp);}}
 private void text(Map<String,Object> r,String key,int max,boolean required){String v=s(r.get(key));check(v.length()<=max&&(!required||!v.trim().isEmpty()),"字段 "+key+" 不能为空或超过长度限制");}
 @GetMapping public synchronized Object get(HttpServletRequest r)throws IOException{return ok(read(access.web(r)));}
 @PutMapping public synchronized Object save(HttpServletRequest req,@RequestBody Map<String,Object> body)throws IOException{EhrActor a=access.web(req);Map<String,Object> old=read(a);if(EhrService.num(old.get("version"))!=EhrService.num(body.get("version")))throw new EhrException(409,"规则已被其他人员修改，请刷新后重试");List<Map<String,Object>> groups=rows(body.get("groups"),2000),rules=rows(body.get("rules"),5000),history=rows(old.get("history"),200),previous=rows(old.get("rules"),5000);Set<String> gids=new HashSet<>(),ids=new HashSet<>();Map<String,String> kinds=new HashMap<>();for(Map<String,Object> g:groups){text(g,"id",100,true);text(g,"name",150,true);check(gids.add(s(g.get("id"))),"分组ID重复");check(Arrays.asList("indicator","risk","composite","segments").contains(s(g.get("kind"))),"分组类型无效");kinds.put(s(g.get("id")),s(g.get("kind")));}
 for(Map<String,Object> r:rules){text(r,"id",100,true);text(r,"name",200,true);text(r,"description",2000,false);text(r,"reference",1000,false);text(r,"referenceUrl",1000,false);String url=s(r.get("referenceUrl"));check(url.isEmpty()||url.matches("https?://[^\\s]+"),"参考链接须为http或https网址");check(ids.add(s(r.get("id"))),"规则ID重复");check(s(r.get("kind")).equals(kinds.get(s(r.get("groupId")))),"规则类型和所属分组不一致");check(Arrays.asList("threshold","interval","combined").contains(s(r.get("method"))),"判定方式无效");check(r.get("metrics") instanceof List&&((List<?>)r.get("metrics")).size()<=30,"适用指标无效");Set<String> metrics=new HashSet<>();for(Object m:(List<?>)r.get("metrics")){check(s(m).length()<=100&&!s(m).isEmpty(),"指标编码无效");metrics.add(s(m));}List<Map<String,Object>> conditions=rows(r.get("conditions"),100);if(Boolean.TRUE.equals(r.get("enabled")))check(!conditions.isEmpty()&&!metrics.isEmpty(),"启用规则前请配置指标和判定条件");Set<String> cids=new HashSet<>();for(Map<String,Object> c:conditions){text(c,"id",100,true);text(c,"label",255,true);text(c,"raw",1000,false);check(cids.add(s(c.get("id"))),"判定条件ID重复");check(Arrays.asList("all","any").contains(s(c.get("logic"))),"条件逻辑无效");List<Map<String,Object>> clauses=rows(c.get("clauses"),30);check(!clauses.isEmpty()||!s(c.get("raw")).trim().isEmpty(),"判定条件不能为空");for(Map<String,Object> clause:clauses){check(metrics.contains(s(clause.get("metric"))),"判定条件引用了未选指标");check(Arrays.asList("gt","gte","lt","lte","eq").contains(s(clause.get("operator"))),"比较运算符无效");check(clause.get("value") instanceof Number&&Double.isFinite(((Number)clause.get("value")).doubleValue()),"判定阈值必须是有限数值");}}
 Map<String,Object> prior=previous.stream().filter(p->s(p.get("id")).equals(s(r.get("id")))).findFirst().orElse(null);if(prior==null||!json.writeValueAsString(prior).equals(json.writeValueAsString(r))){if(prior!=null)history.add(map("id",UUID.randomUUID().toString(),"ruleId",prior.get("id"),"name",prior.get("name"),"revision",prior.get("revision"),"savedAt",now(),"savedBy",a.user,"snapshot",prior));r.put("revision",prior==null?1:EhrService.num(prior.get("revision"))+1);r.put("updatedAt",now());}}
 for(Map<String,Object> p:previous)if(!ids.contains(s(p.get("id"))))history.add(map("id",UUID.randomUUID().toString(),"ruleId",p.get("id"),"name",p.get("name"),"revision",p.get("revision"),"savedAt",now(),"savedBy",a.user,"snapshot",p));if(history.size()>100)history=new ArrayList<>(history.subList(history.size()-100,history.size()));Map<String,Object> next=map("version",EhrService.num(old.get("version"))+1,"groups",groups,"rules",rules,"history",history);write(a,next);return ok(next);}
 private List<Map<String,Object>> rawClauses(Map<String,Object> condition,Map<String,Object> rule){List<Map<String,Object>> out=new ArrayList<>();if(!(rule.get("metrics") instanceof List)||((List<?>)rule.get("metrics")).size()!=1)return out;String metric=s(((List<?>)rule.get("metrics")).get(0));Matcher m=Pattern.compile("^([\\[(])?\\s*(-?[0-9]+(?:\\.[0-9]+)?)?\\s*~\\s*(-?[0-9]+(?:\\.[0-9]+)?)?\\s*([\\])])?$").matcher(s(condition.get("raw")).trim());if(!m.matches()||(m.group(2)==null&&m.group(3)==null)||(m.group(2)!=null&&m.group(1)==null)||(m.group(3)!=null&&m.group(4)==null))return out;if(m.group(2)!=null)out.add(map("metric",metric,"operator","[".equals(m.group(1))?"gte":"gt","value",Double.parseDouble(m.group(2))));if(m.group(3)!=null)out.add(map("metric",metric,"operator","]".equals(m.group(4))?"lte":"lt","value",Double.parseDouble(m.group(3))));return out;}
 @PostMapping("/test") public Object test(HttpServletRequest req,@RequestBody Map<String,Object> body)throws IOException{Map<String,Object> data=read(access.web(req));Map<String,Object> rule=rows(data.get("rules"),5000).stream().filter(r->s(r.get("id")).equals(s(body.get("ruleId")))).findFirst().orElseThrow(()->new EhrException(404,"规则不存在"));check(body.get("values") instanceof Map,"请填写测试指标值");Map<?,?> values=(Map<?,?>)body.get("values");List<Object> results=new ArrayList<>();for(Map<String,Object> c:rows(rule.get("conditions"),100)){List<Map<String,Object>> clauses=rows(c.get("clauses"),30);if(clauses.isEmpty())clauses=rawClauses(c,rule);String eligibility="",gender=s(c.get("gender")),inputGender=s(body.get("gender"));if(gender.equals("1")||gender.equals("2")){if(inputGender.isEmpty())eligibility="missing";else if(!gender.equals(inputGender))eligibility="not_applicable";}double minAge=EhrService.num(c.get("minAge")),maxAge=EhrService.num(c.get("maxAge"));if(minAge>0||maxAge>0){String age=s(body.get("age"));if(age.isEmpty())eligibility="missing";else{double n;try{n=Double.parseDouble(age);}catch(NumberFormatException ex){throw new EhrException(422,"测试年龄须为数值");}check(Double.isFinite(n)&&n>=0&&n<=150,"测试年龄无效");if((minAge>0&&n<minAge)||(maxAge>0&&n>maxAge))eligibility="not_applicable";}}if(!eligibility.isEmpty()){results.add(map("label",c.get("label"),"level",c.get("level"),"status",eligibility));continue;}String status="unsupported";if(!clauses.isEmpty()){boolean any="any".equals(s(c.get("logic"))),truth=!any,unknown=false,decisive=false;for(Map<String,Object> f:clauses){Object input=values.get(s(f.get("metric")));if(input==null||s(input).trim().isEmpty()){unknown=true;continue;}double x;try{x=Double.parseDouble(s(input));}catch(NumberFormatException ex){throw new EhrException(422,"测试指标值必须是数值");}check(Double.isFinite(x),"测试值必须是有限数值");double y=((Number)f.get("value")).doubleValue();String op=s(f.get("operator"));boolean match=op.equals("gt")?x>y:op.equals("gte")?x>=y:op.equals("lt")?x<y:op.equals("lte")?x<=y:x==y;if(any&&match){truth=true;decisive=true;}if(!any&&!match){truth=false;decisive=true;}}status=unknown&&!decisive?"missing":truth?"matched":"unmatched";}results.add(map("label",c.get("label"),"level",c.get("level"),"status",status));}return ok(map("results",results,"ruleName",rule.get("name"),"revision",rule.get("revision")));}
}
